{"command":"python - <<'PY'
import pandas as pd, numpy as np
from statsmodels.tsa.filters.hp_filter import hpfilter

pce = pd.read_excel('/root/ERP-2025-table10.xls', sheet_name='B10', header=None)
pfi = pd.read_excel('/root/ERP-2025-table12.xls', sheet_name='B12', header=None)
cpi = pd.read_excel('/root/CPI.xlsx').set_index('Year')['CPI_2024']

def parse_table(df):
    series = {}
    # annual rows until 2020
    for i in range(len(df)):
        label = str(df.iloc[i,0]).strip()
        if label.endswith('.') and ':' not in label:
            try:
                year = int(label.rstrip('.'))
            except:
                continue
            val = pd.to_numeric(df.iloc[i,1], errors='coerce')
            if not pd.isna(val):
                series[year] = float(val)
    # quarterly section: collect by year in row labels
    current_year=None
    quarters={}
    for i in range(len(df)):
        label = str(df.iloc[i,0]).strip()
        if label.startswith(tuple(str(y) for y in range(2021,2025))):
            # e.g. 2021: I.
            try:
                current_year=int(label.split(':')[0])
                q=label.split(':')[1].strip().split()[0]
            except:
                continue
        elif label in ['I.','II.','III.','IV.','III p.','IV p.'] or label.startswith(('I.','II.','III','IV')):
            q=label.split()[0]
        else:
            continue
        if current_year is not None and q[0] in 'IIIIVX':
            val = pd.to_numeric(df.iloc[i,1], errors='coerce')
            if not pd.isna(val):
                quarters.setdefault(current_year,[]).append(float(val))
    for y,vals in quarters.items():
        series[y]=float(np.mean(vals))
    return series

pce_s = parse_table(pce)
pfi_s = parse_table(pfi)
# inspect years present
print(sorted([y for y in pce_s if y>=2020]))
print(sorted([y for y in pfi_s if y>=2020]))

years=range(1973,2025)
pce_ser = pd.Series([pce_s[y] for y in years], index=years)
pfi_ser = pd.Series([pfi_s[y] for y in years], index=years)
cpi_ser = cpi.reindex(years)
real_pce = pce_ser / cpi_ser
real_pfi = pfi_ser / cpi_ser
cycle_pce,_=hpfilter(np.log(real_pce),lamb=100)
cycle_pfi,_=hpfilter(np.log(real_pfi),lamb=100)
cor = np.corrcoef(cycle_pce, cycle_pfi)[0,1]
print('cor',cor)
print('2021-2024 pce', [pce_s[y] for y in range(2021,2025)])
print('2021-2024 pfi', [pfi_s[y] for y in range(2021,2025)])
PY"}

